import re,statistics
from pathlib import Path
root=Path('tmp/strata-router-tiles-20261004/results')
for math,minimum in [('fast',1.05),('conservative',1.02)]:
 text=(root/('native-'+math+'-47.log')).read_text()
 for tokens in (512,4096):
  pairs={}
  for n,pair,mode,seconds in re.findall(r'ROUTER_TILES_TIME tokens=(\d+) pair=(\d+) mode=(\d+) seconds=([0-9.]+)',text):
   if int(n)==tokens:pairs.setdefault(int(pair),{})[int(mode)]=float(seconds)
  assert len(pairs)==7 and all(set(v)=={0,1} and min(v.values())>0 for v in pairs.values())
  ratio=statistics.median(v[0]/v[1] for v in pairs.values())
  print('ROUTER_TILES_NATIVE_GATE',math,tokens,ratio,flush=True)
  assert ratio>=minimum
